/// <summary>
/// The extension class for Inventroy transfer order updates.
/// </summary>
[ExtensionOf(classStr(InventTransferUpd))]
final class METInventTransferUpd_Extension
{    
}

Method.Source:
    /// <summary>
    /// Extension of insert journal line method for transfer orders.
    /// </summary>
    protected void insertJournalLines()
    {
        #OCCRetryCount
        InventTransferJourLine      inventTransferJourLine;
        InventSite inventSite;
        MetItemSiteSettingsSetup metItemSiteSettingsSetup;
        
        next insertJournalLines();

        if (inventTransferJour.UpdateType == InventTransferUpdateType::Receive)
        {        
            try
            {
                inventSite = InventSite::find(InventLocation::find(inventTransferJour.InventLocationIdTo).InventSiteId);

                if (inventSite && inventSite.METAutoUpdateItemStatusUponReceipt)
                {            
                    while select inventTransferJourLine
                        where inventTransferJourLine.TransferId == inventTransferJour.TransferId &&
                        inventTransferJourLine.VoucherId == inventTransferJour.VoucherId
                    {
                        metItemSiteSettingsSetup = MetItemSiteSettingsSetup::find(inventTransferJourLine.ItemId, inventSite.SiteId, true);
            
                        if (metItemSiteSettingsSetup && metItemSiteSettingsSetup.ItemStatus == METConstants::NewStr)
                        {
                            metItemSiteSettingsSetup.ItemStatus = METConstants::Active;
                            metItemSiteSettingsSetup.update();
                        }   
                        
                        // Update child items as well.
                        MetItemSiteSettingsSetup::updateChildItemSiteStatus(inventTransferJourLine.ItemId, inventSite.SiteId);
                    }
                }
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
        }
    }
